insert into turmas (nome, turno) values ('3º A','Manhã'),('3º B','Tarde') on conflict do nothing;
insert into modulos (disciplina_id, nome, ordem) select id, 'Brasil República', 0 from disciplinas where nome='História';
insert into modulos (disciplina_id, nome, ordem) select id, 'Mundo contemporâneo', 1 from disciplinas where nome='História';
insert into modulos (disciplina_id, nome, ordem) select id, 'Território brasileiro', 2 from disciplinas where nome='Geografia';
insert into modulos (disciplina_id, nome, ordem) select id, 'Meio ambiente', 3 from disciplinas where nome='Geografia';
insert into modulos (disciplina_id, nome, ordem) select id, 'Pensamento moderno', 4 from disciplinas where nome='Filosofia';
insert into modulos (disciplina_id, nome, ordem) select id, 'Os fundadores', 5 from disciplinas where nome='Sociologia';
insert into modulos (disciplina_id, nome, ordem) select id, 'Cultura e sociedade', 6 from disciplinas where nome='Sociologia';
insert into questoes (disciplina_id, competencia_id, enunciado, alternativas, correta, comentario) select d.id, c.id, 'A Consolidação das Leis do Trabalho (CLT), de 1943, representou, no governo de Getúlio Vargas:', '["o fim da intervenção do Estado nas relações de trabalho","a regulamentação de direitos trabalhistas com controle estatal sobre os sindicatos","a extinção da jornada de trabalho regulamentada","a privatização das indústrias de base"]'::jsonb, 1, 'A CLT reuniu direitos como salário mínimo e jornada, mas manteve os sindicatos sob tutela do Ministério do Trabalho.' from disciplinas d, competencias c where d.nome='História' and c.area='humanas' and c.codigo='A';
insert into questoes (disciplina_id, competencia_id, enunciado, alternativas, correta, comentario) select d.id, c.id, 'O Departamento de Imprensa e Propaganda (DIP), criado no Estado Novo, tinha como função:', '["garantir a liberdade de imprensa","controlar as informações e divulgar a imagem do regime","financiar jornais de oposição","organizar as eleições presidenciais"]'::jsonb, 1, 'O DIP exercia censura e produzia propaganda oficial para sustentar a imagem do líder e do regime.' from disciplinas d, competencias c where d.nome='História' and c.area='humanas' and c.codigo='A';
insert into questoes (disciplina_id, competencia_id, enunciado, alternativas, correta, comentario) select d.id, c.id, 'A criação da Companhia Siderúrgica Nacional, em 1941, relaciona-se ao projeto de:', '["fortalecer a economia agroexportadora cafeeira","industrialização de base e substituição de importações","abertura irrestrita ao capital estrangeiro","reforma agrária em larga escala"]'::jsonb, 1, 'A siderurgia era a base da indústria pesada, pilar da substituição de importações.' from disciplinas d, competencias c where d.nome='História' and c.area='humanas' and c.codigo='A';
insert into questoes (disciplina_id, competencia_id, enunciado, alternativas, correta, comentario) select d.id, c.id, 'A migração do campo para as cidades, intensificada a partir dos anos 1930, provocou:', '["esvaziamento das capitais regionais","crescimento urbano acelerado e pressão por moradia e serviços","redução da oferta de mão de obra industrial","fim das atividades agrícolas no país"]'::jsonb, 1, 'A industrialização atraiu trabalhadores rurais, e as cidades cresceram mais rápido que a infraestrutura.' from disciplinas d, competencias c where d.nome='História' and c.area='humanas' and c.codigo='B';
insert into questoes (disciplina_id, competencia_id, enunciado, alternativas, correta, comentario) select d.id, c.id, 'A Marcha para o Oeste, lançada durante o Estado Novo, buscava:', '["estimular a ocupação e a integração do interior do país","transferir a capital para o litoral","proibir a migração entre regiões","fechar as fronteiras agrícolas"]'::jsonb, 0, 'A campanha incentivava a ocupação do Centro-Oeste e da Amazônia, integrando o território ao mercado nacional.' from disciplinas d, competencias c where d.nome='História' and c.area='humanas' and c.codigo='B';
insert into questoes (disciplina_id, competencia_id, enunciado, alternativas, correta, comentario) select d.id, c.id, 'A propaganda política em regimes autoritários costuma:', '["estimular o debate plural entre grupos","construir uma imagem unificada do líder e silenciar vozes dissidentes","eliminar os símbolos nacionais","reduzir o papel dos meios de comunicação"]'::jsonb, 1, 'A propaganda cria um consenso aparente em torno do líder e marginaliza a crítica.' from disciplinas d, competencias c where d.nome='História' and c.area='humanas' and c.codigo='C';
insert into simulados (titulo, disciplina_id, minutos) select 'Era Vargas e Estado Novo', id, 30 from disciplinas where nome='História';
insert into simulado_questoes (simulado_id, questao_id, ordem) select s.id, q.id, row_number() over (order by q.created_at, q.enunciado) from simulados s, questoes q where s.titulo='Era Vargas e Estado Novo' and q.enunciado in ('A Consolidação das Leis do Trabalho (CLT), de 1943, representou, no governo de Getúlio Vargas:','O Departamento de Imprensa e Propaganda (DIP), criado no Estado Novo, tinha como função:','A criação da Companhia Siderúrgica Nacional, em 1941, relaciona-se ao projeto de:','A migração do campo para as cidades, intensificada a partir dos anos 1930, provocou:','A Marcha para o Oeste, lançada durante o Estado Novo, buscava:','A propaganda política em regimes autoritários costuma:');
insert into simulado_turmas (simulado_id, turma_id) select s.id, t.id from simulados s, turmas t where s.titulo='Era Vargas e Estado Novo';
